import { Component, useMemo, useState, type ReactNode } from 'react'
import './App.css'
import { aggregateForecastOffloadRate, assessShipmentValue, buildForecasts, calculatePotentialLossAvoidable, customerProfiles, demoOffloadMetrics, demoOutcomes, evaluateRecoveryScenario, evaluateRecoverySensitivity, explainRecoveryEvaluation, formatCurrency, formatKg, getShipmentScenarioLoss, getWeather, predictionConfig, recordRecoveryDecision, recoveryCases, recoveryOptions, shipments, summarizeAnalytics, weatherAssessments, type CustomerValueProfile, type FlightCapacityForecast, type RecoveryDecision, type RecoveryOption, type Shipment } from './domain'
import { OffloadTrendChart } from './OffloadTrendChart'
