function RecoveryWorkspacePage({ onNavigate, onSelect }: { onNavigate: (item: NavItem) => void; onSelect: (option: RecoveryOption, scenario: 'no-intervention' | 'preventive' | 'recover') => void }) {
  const [scenario, setScenario] = useState<'no-intervention' | 'preventive' | 'recover'>('recover')
  const evaluations = useMemo(() => evaluateRecoveryScenario(scenario), [scenario])
  return <div className="app-shell"><WorkspaceSidebar active="Recovery Plans" onNavigate={onNavigate} /><main className="main-content shipment-page"><header className="topbar"><div className="crumb">CATHAY ROUTER <span>/</span> RECOVERY PLANS</div><span className="demo-label">WORKSPACE</span></header><div className="page-heading"><div><p className="eyebrow">P2 · NETWORK RECOVERY · DEMO DATA</p><h1>Recovery Plan Comparison</h1><p className="subtitle">Rank alternatives by total expected loss, usable capacity, deadline feasibility, and network effects.</p></div><DemoTag /></div><div className="scenario-tabs"><span>Decision scenario</span>{([['no-intervention', 'No intervention'], ['preventive', 'Preventive intervention'], ['recover', 'Offload and recover']] as const).map(([key, label]) => <button key={key} className={scenario === key ? 'selected' : ''} onClick={() => setScenario(key)}>{label}</button>)}</div><section className="panel"><div className="panel-heading"><div><h2>Candidate recovery plans</h2><p>Each scenario is reevaluated against the same hard constraints and modeled loss components.</p></div></div><div className="table-wrap"><table><thead><tr><th>ORIGINAL → ALTERNATIVE</th><th>CAPACITY STATUS</th><th>FUEL / WEATHER</th><th>ARRIVAL / DEADLINE</th><th>TOTAL EXPECTED LOSS</th><th>OPTIMIZATION EVIDENCE</th><th /></tr></thead><tbody>{evaluations.map((evaluation) => { const option = evaluation.option; return <tr key={option.id} onClick={() => onSelect(option, scenario)}><td><strong>{option.original}</strong><small>{option.alternative}</small></td><td><b>{formatKg(option.usableCapacityKg)} usable</b><small>{option.capacityStatus} · {option.feasibility}% feasible</small></td><td><b>{option.fuelConstraint}</b><small>{option.weatherExposure}</small></td><td><b>{option.expectedArrival}</b><small>{option.delayHours}h delay · deadline assessed</small></td><td><strong>{formatCurrency(evaluation.costBreakdown.totalExpectedLoss)}</strong><small>Scenario-evaluated cost</small></td><td><small>{evaluation.terminationReason}</small></td><td><button className="row-action" aria-label={`Review ${option.id}`}><Icon name="arrow" size={15} /></button></td></tr> })}</tbody></table></div></section><section className="network-panel"><div><p className="eyebrow">DOMINO-EFFECT ANALYSIS · SIMULATED</p><h2>Accepting cargo on CX289 may transfer the constraint</h2><p>CX289 has a nominal buffer, but FRA thunderstorms and a 600 kg fuel-related payload constraint reduce usable capacity. The downstream exposure is marked uncertain rather than treated as guaranteed.</p></div><div className="network-steps"><span>CX257<br /><b>1,800 kg shortfall</b></span><Icon name="arrow" size={14} /><span>CX289<br /><b>1,200 kg usable</b></span><Icon name="arrow" size={14} /><span>Downstream<br /><b>Impact uncertain</b></span></div></section><footer>Recovery recommendations are simulated decision support. No capacity is reserved and no operational action is applied.</footer></main></div>
}

function AnalyticsWorkspacePage({ onNavigate }: { onNavigate: (item: NavItem) => void }) {
  const summary = summarizeAnalytics()
  const rateLabel = (metric: { rate: number | null; numerator: number; denominator: number }) => metric.rate === null ? 'Unavailable' : `${Math.round(metric.rate * 100)}% (${metric.numerator}/${metric.denominator})`
  return <div className="app-shell"><WorkspaceSidebar active="Analytics" onNavigate={onNavigate} /><main className="main-content shipment-page analytics-page"><header className="topbar"><div className="crumb">CATHAY ROUTER <span>/</span> ANALYTICS</div><span className="demo-label">WORKSPACE</span></header><div className="page-heading"><div><h1>Prediction Analytics</h1><p className="subtitle">Evaluate saved forecasts and recorded outcomes separately from the Prediction workspace.</p></div><DemoTag /></div><section className="analytics-note"><strong>{summary.sufficientSample ? 'Sample sufficient for this view' : `Insufficient sample: ${summary.sampleSize} simulated flight records; 30+ recommended`}</strong><span>These demo metrics describe the fixture, not production model performance.</span><small>Forecast and actual values are matched by the same flight-departure cohort. No post-departure information is used to rebuild the saved prediction.</small></section><section className="kpi-grid analytics-kpis"><Kpi title="Flights flagged by prediction" value={`${Math.round(summary.predictedRate * 100)}%`} detail={`${summary.sampleSize} simulated flight records`} tone="warning" /><Kpi title="Flights with recorded offload" value={`${Math.round(summary.actualRate * 100)}%`} detail="Recorded flight outcomes" tone="neutral" /><Kpi title="False alarms" value={rateLabel(summary.falseAlarm)} detail="Predicted offload, actual no offload" tone="danger" /><Kpi title="Missed offloads" value={rateLabel(summary.missedOffload)} detail="Actual offload, not predicted" tone="danger" /><Kpi title="Intervention success" value={rateLabel(summary.interventionSuccess)} detail="Outcome after recorded intervention" tone="blue" /></section><section className="panel"><div className="panel-heading"><div><h2>Prediction quality</h2><p>Mean absolute per-flight error and the aggregate predicted-to-actual rate gap are shown separately.</p></div><DemoTag /></div><div className="activity-summary"><span><small>MEAN ABSOLUTE PER-FLIGHT RATE ERROR</small><b>{summary.meanAbsoluteProbabilityError === null ? 'Unavailable' : `${(summary.meanAbsoluteProbabilityError * 100).toFixed(1)} pp`}</b></span><span><small>AGGREGATE FLIGHT RATE GAP</small><b>{summary.flightRateError === null ? 'Unavailable' : `${(summary.flightRateError * 100).toFixed(1)} pp`}</b></span><span><small>FORECAST LEAD TIME</small><b>{summary.leadTimeHours === null ? 'Unavailable' : `${summary.leadTimeHours.toFixed(1)}h`}</b></span><span><small>OBSERVATIONS</small><b>{summary.sampleSize}</b></span></div><div className="analytics-note"><strong>Definitions:</strong><span>False alarm = false positives / predicted positives. Missed offload = false negatives / actual offloads. Intervention success = interventions without an actual offload / recorded interventions.</span></div></section><OffloadTrendChart /><section className="panel"><div className="panel-heading"><div><h2>Business impact and outcome evidence</h2><p>Estimated value at risk is compared with recorded realised loss; recovery cost is unavailable in current fixtures.</p></div></div><div className="table-wrap"><table><thead><tr><th>FLIGHT / ROUTE</th><th>PREDICTED</th><th>ACTUAL</th><th>VALUE AT RISK</th><th>REALISED LOSS</th><th>INTERVENTION</th><th>DATA QUALITY</th></tr></thead><tbody>{demoOutcomes.map((outcome) => <tr key={outcome.flightId}><td><strong>{outcome.flightId}</strong><small>{outcome.route} · {outcome.category}</small></td><td>{Math.round(outcome.predictedRate * 100)}%</td><td>{Math.round(outcome.actualRate * 100)}%</td><td>{formatCurrency(outcome.valueAtRisk)}</td><td>{formatCurrency(outcome.realisedLoss)}</td><td>{outcome.interventionApplied ? 'Recorded' : 'None recorded'}<small>Association is not causation</small></td><td>{summary.recoveryCostDataAvailable ? 'Recovery cost available' : 'Recovery cost unavailable'}</td></tr>)}</tbody></table></div><div className="analytics-note"><strong>Limitations:</strong><span>Route, aircraft, cargo category, disruption cause and fuel/weather breakdowns should only be compared after sample-size and data-quality checks. Current outcomes are four simulated flights.</span></div></section><footer>Analytics evaluates recorded outcomes and decisions. It does not generate operational predictions or claim that an intervention caused a favourable outcome.</footer></main></div>
}

export function LegacyAnalyticsWorkspacePage({ onNavigate }: { onNavigate: (item: NavItem) => void }) {
  const summary = summarizeAnalytics()
  return <div className="app-shell"><WorkspaceSidebar active="Analytics" onNavigate={onNavigate} /><main className="main-content shipment-page"><header className="topbar"><div className="crumb">CATHAY ROUTER <span>/</span> ANALYTICS</div><span className="demo-label">WORKSPACE</span></header><div className="page-heading"><div><p className="eyebrow">P3 · PREDICTION QUALITY · DEMO DATA</p><h1>Prediction Analytics</h1><p className="subtitle">Compare forecasts with recorded outcomes and separate correlation from operational cause.</p></div><DemoTag /></div><section className="kpi-grid analytics-kpis"><Kpi title="Predicted offload rate" value={`${Math.round(summary.predictedRate * 100)}%`} detail="Forecast population: 4 demo flights" tone="warning" /><Kpi title="Actual offload rate" value={`${Math.round(summary.actualRate * 100)}%`} detail="Recorded demo outcomes" tone="neutral" /><Kpi title="False alarm rate" value={`${Math.round(summary.falseAlarmRate * 100)}%`} detail="Predicted, not actually offloaded" tone="danger" /><Kpi title="Missed offload rate" value={`${Math.round(summary.missedOffloadRate * 100)}%`} detail="Actual, not predicted" tone="danger" /><Kpi title="Intervention success" value={`${Math.round(summary.interventionSuccessRate * 100)}%`} detail={`${summary.interventionCount} interventions observed`} tone="blue" /></section><section className="panel"><div className="panel-heading"><div><h2>Predicted versus actual outcomes</h2><p>Demo records by route and cargo category. Actual reason fields remain operational evidence, not weather correlation.</p></div></div><div className="table-wrap"><table><thead><tr><th>FLIGHT / CATEGORY</th><th>PREDICTED RATE</th><th>ACTUAL RATE</th><th>VALUE AT RISK</th><th>REALISED LOSS</th><th>INTERVENTION</th></tr></thead><tbody>{demoOutcomes.map((outcome) => <tr key={outcome.flightId}><td><strong>{outcome.flightId}</strong><small>{outcome.route} · {outcome.category}</small></td><td>{Math.round(outcome.predictedRate * 100)}%</td><td>{Math.round(outcome.actualRate * 100)}%</td><td>{formatCurrency(outcome.valueAtRisk)}</td><td>{formatCurrency(outcome.realisedLoss)}</td><td><RiskBadge level={outcome.interventionApplied ? 'Low' : outcome.actualOffload ? 'High' : 'Moderate'} /><small>{outcome.interventionApplied ? 'Applied in demo record' : 'No intervention recorded'}</small></td></tr>)}</tbody></table></div></section><section className="analytics-note"><strong>Evaluation notes</strong><span>Lead time: {summary.leadTimeHours}h average · Estimated value at risk: {formatCurrency(summary.estimatedValueAtRisk)} · Realised loss: {formatCurrency(summary.realisedLoss)}</span><small>Fixtures are illustrative. Route, aircraft, cargo category, and disruption-cause breakdowns should be calculated from recorded operational outcomes when integrated.</small></section><footer>Analytics are simulated and do not claim that weather caused an offload without a recorded operational reason.</footer></main></div>
}

function PredictionWorkspacePage({ onNavigate, onSelectFlight }: { onNavigate: (item: NavItem) => void; onSelectFlight: (flight: FlightCapacityForecast) => void }) {
  const [query, setQuery] = useState('')
  const [filter, setFilter] = useState<'All' | 'High risk' | 'Fuel' | 'Weather'>('All')
  const [sort, setSort] = useState<'risk' | 'value' | 'shortfall' | 'confidence'>('value')
  const [riskThreshold, setRiskThreshold] = useState(predictionConfig.highRiskProbabilityThreshold)
  const forecasts = useMemo(() => buildForecasts(), [])
  const filtered = useMemo(() => forecasts.filter((flight) => {
    const matchesQuery = `${flight.flightId} ${flight.route}`.toLowerCase().includes(query.toLowerCase())
    const matchesFilter = filter === 'All' || (filter === 'High risk' ? flight.forecastOffloadProbability >= riskThreshold : filter === 'Fuel' ? flight.forecastAdditionalFuelWeight > 0 : flight.weatherRiskLevel !== 'Low')
    return matchesQuery && matchesFilter
  }).sort((a, b) => sort === 'risk' ? b.forecastOffloadProbability - a.forecastOffloadProbability : sort === 'shortfall' ? b.forecastCapacityShortfall - a.forecastCapacityShortfall : sort === 'confidence' ? a.forecastConfidence - b.forecastConfidence : b.valueAtRisk - a.valueAtRisk), [filter, forecasts, query, riskThreshold, sort])
  const selectedShipments = shipments.filter((shipment) => filtered.some((flight) => flight.flightId === shipment.flightId))
  const predictedRate = aggregateForecastOffloadRate(filtered)
  const highRisk = filtered.filter((flight) => flight.forecastOffloadProbability >= riskThreshold).length
  const exposedShipments = selectedShipments.filter((shipment) => shipment.offloadProbability >= .2)
  const valueAtRisk = filtered.reduce((sum, flight) => sum + flight.valueAtRisk, 0)
  return <div className="app-shell"><WorkspaceSidebar active="Predictions" onNavigate={onNavigate} /><main className="main-content shipment-page prediction-page"><header className="topbar"><div className="crumb">CATHAY ROUTER <span>/</span> PREDICTIONS</div><div className="top-actions"><label className="global-search"><Icon name="search" size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search flight or route" aria-label="Search predictions" /></label><DemoTag /></div></header><div className="page-heading"><div><h1>Prediction Workspace</h1><p className="subtitle">Find capacity risks early enough to protect shipments before the loading decision.</p></div><DemoTag /></div><section className="kpi-grid prediction-kpis"><Kpi title="Forecast booked-weight shortfall" value={predictedRate === null ? 'Unavailable' : `${Math.round(predictedRate * 100)}%`} detail="Average forecast capacity shortfall as a share of booked cargo weight · simulated" tone="warning" /><Kpi title="Flights at review threshold" value={`${highRisk}`} detail={`Triage guideline: at least ${Math.round(riskThreshold * 100)}%`} tone="danger" /><Kpi title="Shipments at risk" value={`${exposedShipments.length}`} detail="Unique shipments with elevated shipment-level probability" tone="blue" /><Kpi title="Estimated value at risk" value={formatCurrency(valueAtRisk)} detail="Cargo/customer impact proxy · simulated" tone="warning" /><Kpi title="Potential loss avoidable" value={formatCurrency(calculatePotentialLossAvoidable(selectedShipments))} detail="Baseline loss minus feasible preventive scenario · simulated" tone="success" /></section><section className="prediction-toolbar"><span>Filter forecast</span>{(['All', 'High risk', 'Fuel', 'Weather'] as const).map((item) => <button key={item} className={filter === item ? 'selected' : ''} onClick={() => setFilter(item)}>{item}</button>)}<span className="toolbar-spacer" /><label>Review threshold <input aria-label="High-risk review threshold percentage" type="number" min="0" max="100" value={Math.round(riskThreshold * 100)} onChange={(event) => setRiskThreshold(Math.min(1, Math.max(0, Number(event.target.value) / 100)))} />%</label><small>{predictionConfig.thresholdMeaning}</small><span className="toolbar-spacer" /><span>Sort by</span>{([['value', 'Value at risk'], ['risk', 'Offload probability'], ['shortfall', 'Capacity shortfall'], ['confidence', 'Lowest confidence']] as const).map(([key, label]) => <button key={key} className={sort === key ? 'selected' : ''} onClick={() => setSort(key)}>{label}</button>)}</section><section className="panel"><div className="panel-heading"><div><h2>Forecast risk and evidence</h2><p>Illustrative rule-based results from synthetic inputs; this demo has no trained model or live feed.</p></div><DemoTag /></div><div className="table-wrap"><table><thead><tr><th>FLIGHT / ROUTE</th><th>DEMO OFFLOAD RISK SCORE</th><th>FORECAST SHORTFALL</th><th>CAPACITY</th><th>VALUE AT RISK</th></tr></thead><tbody>{filtered.map((flight) => <tr key={flight.flightId} onClick={() => onSelectFlight(flight)}><td><strong>{flight.flightId}</strong><small>{flight.route} · {flight.departure}<br />{flight.aircraftType}</small></td><td><strong>{Math.round(flight.forecastOffloadProbability * 100)}%</strong><small>Weather input confidence: {flight.forecastConfidence}%</small></td><td>{Math.round(flight.predictedOffloadRate * 100)}%<small>of booked weight · {flight.affectedShipments} shipment(s) flagged</small></td><td><b>{formatKg(flight.forecastCargoCapacity)}</b><small>{flight.forecastCapacityShortfall ? `${formatKg(flight.forecastCapacityShortfall)} shortfall` : 'No weight shortfall'}</small></td><td><b>{formatCurrency(flight.valueAtRisk)}</b><small>expected loss proxy</small></td></tr>)}</tbody></table></div></section><section className="panel prevention-plan-link"><div className="panel-heading"><div><p className="eyebrow">NEXT STEP · PREVENTION</p><h2>Review the Prevention Plan</h2><p>Compare early, simulated options for unconfirmed offload risks. Confirmed offloads are handled separately in Recovery Plans.</p></div><button className="outline-button" onClick={() => onNavigate('Prevention Plan')}>Open Prevention Plan <Icon name="arrow" size={14} /></button></div></section><footer>Static demo forecasts. Aircraft substitution, baggage and ULD compatibility are unavailable in current demo fixtures and are not inferred.</footer></main></div>
}

export function LegacyPredictionWorkspacePage({ onNavigate, onSelectFlight, onSelectShipment }: { onNavigate: (item: NavItem) => void; onSelectFlight: (flight: FlightCapacityForecast) => void; onSelectShipment: (shipment: Shipment) => void }) {
  const forecasts = useMemo(() => buildForecasts(), [])
  const [query, setQuery] = useState('')
  const [filter, setFilter] = useState<'All' | 'High risk' | 'Fuel' | 'Weather'>('All')
  const [sort, setSort] = useState<'risk' | 'value' | 'shortfall' | 'confidence'>('value')
  const filtered = useMemo(() => forecasts.filter((flight) => {
    const matchesQuery = `${flight.flightId} ${flight.route}`.toLowerCase().includes(query.toLowerCase())
    const matchesFilter = filter === 'All' || (filter === 'High risk' ? flight.forecastOffloadProbability >= .25 : filter === 'Fuel' ? flight.forecastAdditionalFuelWeight > 0 : flight.weatherRiskLevel !== 'Low')
    return matchesQuery && matchesFilter
  }).sort((a, b) => sort === 'risk' ? b.forecastOffloadProbability - a.forecastOffloadProbability : sort === 'shortfall' ? b.forecastCapacityShortfall - a.forecastCapacityShortfall : sort === 'confidence' ? a.forecastConfidence - b.forecastConfidence : b.valueAtRisk - a.valueAtRisk), [filter, forecasts, query, sort])
  const predictedRate = aggregateForecastOffloadRate(filtered) ?? 0
  const highRisk = filtered.filter((flight) => flight.forecastOffloadProbability >= .25).length
  const exposedShipments = shipments.filter((shipment) => filtered.some((flight) => flight.flightId === shipment.flightId) && shipment.offloadProbability >= .2)
  const valueAtRisk = filtered.reduce((sum, flight) => sum + flight.valueAtRisk, 0)
  return <div className="app-shell"><WorkspaceSidebar active="Predictions" onNavigate={onNavigate} /><main className="main-content shipment-page prediction-page"><header className="topbar"><div className="crumb">CATHAY ROUTER <span>/</span> PREDICTIONS</div><div className="top-actions"><label className="global-search"><Icon name="search" size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search flight or route" aria-label="Search predictions" /></label><span className="demo-label">WORKSPACE</span></div></header><div className="page-heading"><div><h1>Prediction Workspace</h1><p className="subtitle">Find capacity risks early enough to protect shipments before the loading decision.</p></div><DemoTag /></div><section className="kpi-grid prediction-kpis"><Kpi title="Predicted offload rate" value={`${Math.round(predictedRate * 100)}%`} detail={`${filtered.length} flights · eligible forecast population`} tone="warning" /><Kpi title="Flights at high risk" value={`${highRisk}`} detail="Configurable triage guide: >=25%" tone="danger" /><Kpi title="Shipments at risk" value={`${exposedShipments.length}`} detail="Unique shipments with elevated probability" tone="blue" /><Kpi title="Estimated value at risk" value={formatCurrency(valueAtRisk)} detail="Cargo/customer impact proxy · simulated" tone="warning" /><Kpi title="Potential loss avoidable" value={formatCurrency(Math.round(valueAtRisk * .34))} detail="Intervention comparison · illustrative" tone="success" /></section><section className="prediction-toolbar"><span>Filter forecast</span>{(['All', 'High risk', 'Fuel', 'Weather'] as const).map((item) => <button key={item} className={filter === item ? 'selected' : ''} onClick={() => setFilter(item)}>{item}</button>)}<span className="toolbar-spacer" /><span>Sort by</span>{([['value', 'Value at risk'], ['risk', 'Offload probability'], ['shortfall', 'Capacity shortfall'], ['confidence', 'Lowest confidence']] as const).map(([key, label]) => <button key={key} className={sort === key ? 'selected' : ''} onClick={() => setSort(key)}>{label}</button>)}</section><ForecastTable forecasts={filtered} onSelect={onSelectFlight} /><section className="prediction-analysis-grid"><section className="panel"><div className="panel-heading"><div><h2>Fuel and Weather Risk Analysis</h2><p>Each factor is connected to a supported operational pathway.</p></div><DemoTag /></div><div className="risk-analysis-list">{filtered.map((flight) => <article className="risk-analysis-card" key={flight.flightId}><div><strong>{flight.flightId} · {flight.route}</strong><small>{flight.aircraftType} · updated {flight.fuelEstimateTimestamp}</small></div><RiskBadge level={flight.weatherRiskLevel} /><p><b>Fuel:</b> {flight.forecastAdditionalFuelWeight ? `+${formatKg(flight.forecastAdditionalFuelWeight)} vs plan reduces supported payload by ${formatKg(flight.originalCargoCapacity - flight.forecastCargoCapacity)}.` : 'No additional fuel requirement currently supported.'} <b>Weather:</b> {flight.expectedOperationalImpact}</p><small className="risk-driver-line">Drivers: {flight.weatherRiskDrivers.join(', ')} · {flight.forecastConfidence}% confidence</small></article>)}</div></section><section className="panel"><div className="panel-heading"><div><h2>Recommended Preventive Actions</h2><p>Ranked by potential loss reduction and feasibility.</p></div></div><div className="recommendation-list">{filtered.filter((flight) => flight.forecastCapacityShortfall > 0 || flight.weatherRiskLevel === 'High').map((flight) => <article key={flight.flightId}><span className="recommendation-number">{flight.forecastCapacityShortfall > 0 ? '01' : '02'}</span><div><strong>Review allocation on {flight.flightId}</strong><p>{flight.forecastCapacityShortfall ? `${formatKg(flight.forecastCapacityShortfall)} shortfall predicted; review lower-impact shipments and compatible alternatives.` : 'Re-evaluate the forecast after the latest weather update before final loading.'}</p><small>{flight.affectedShipments} shipments · {formatCurrency(Math.round(flight.valueAtRisk * .34))} estimated loss avoided · decision before departure</small></div></article>)}</div></section></section><ShipmentTable onSelect={onSelectShipment} /><section className="prediction-history panel"><div className="panel-heading"><div><h2>Forecast History and Accuracy</h2><p>Timeline for CX257. Prediction quality and intervention success remain separate measures.</p></div><DemoTag /></div><div className="history-line"><span><b>08:00</b><small>Initial payload<br />17,000 kg</small></span><span><b>09:10</b><small>Fuel estimate +1,800 kg<br />Payload revised</small></span><span><b>09:20</b><small>Weather confidence 84%<br />Offload risk 33%</small></span><span><b>Pending</b><small>Actual loading outcome<br />Awaiting backend event</small></span></div></section><footer>All prediction results are simulated. Forecast filters update this workspace only; confirmed operational actions require backend approval.</footer></main></div>
}

export function OverviewWorkspacePage({ onNavigate, onSelectFlight, onSelectShipment }: { onNavigate: (item: NavItem) => void; onSelectFlight: (flight: FlightCapacityForecast) => void; onSelectShipment: (shipment: Shipment) => void }) {
  const forecasts = useMemo(() => buildForecasts(), [])
  const rankedFlights = useMemo(() => [...forecasts].sort((a, b) => b.valueAtRisk - a.valueAtRisk), [forecasts])
  const highRiskFlights = forecasts.filter((flight) => flight.forecastOffloadProbability >= .25)
  const exposedShipments = shipments.filter((shipment) => shipment.offloadProbability >= .2)
  const cathayImpact = shipments.reduce((sum, shipment) => sum + shipment.cathayImpact * shipment.offloadProbability, 0)
  const highestRiskShipment = [...exposedShipments].sort((a, b) => b.cargoImpact * b.offloadProbability - a.cargoImpact * a.offloadProbability)[0]
  const weatherAlerts = forecasts.filter((flight) => flight.weatherRiskLevel !== 'Low' || flight.forecastAdditionalFuelWeight > 0)
  const topFlight = rankedFlights[0]
  const ownerForFlight = (flight: FlightCapacityForecast) => flight.forecastCapacityShortfall > 0 ? 'Load planning' : flight.weatherRiskLevel !== 'Low' ? 'Network operations' : 'Cargo control'
  return <div className="app-shell"><WorkspaceSidebar active="Overview" onNavigate={onNavigate} /><main className="main-content overview-page"><header className="topbar"><div className="crumb">CATHAY ROUTER <span>/</span> OVERVIEW</div><div className="top-actions"><span className="data-freshness"><span className="live-dot" />Updated 09:10 UTC</span><DemoTag /></div></header><div className="page-heading"><div><h1>Operations Overview</h1><p className="subtitle">Prioritise the decisions that protect capacity, customers, and Cathay value.</p></div><div className="report-controls"><span>Next 24 hours</span><DemoTag /></div></div><section className="kpi-grid overview-kpis"><Kpi title="Actual offload rate" value={demoOffloadMetrics.actualOffloadRate === null ? 'Unavailable' : `${(demoOffloadMetrics.actualOffloadRate * 100).toFixed(1)}%`} detail={`${demoOffloadMetrics.actualOffloadedShipments} offloaded / ${demoOffloadMetrics.eligibleShipments} eligible · ${demoOffloadMetrics.reportingPeriod.label}`} tone="neutral" /><Kpi title="Predicted offload rate" value={aggregateForecastOffloadRate(forecasts) === null ? 'Unavailable' : `${(aggregateForecastOffloadRate(forecasts)! * 100).toFixed(1)}%`} detail={`${shipments.length} shipment forecast population`} tone="warning" /><Kpi title="Flights high / critical risk" value={`${highRiskFlights.length}`} detail={`${forecasts.length} upcoming flights assessed`} tone="danger" /><Kpi title="Unique shipments at risk" value={`${exposedShipments.length}`} detail="Elevated offload probability >=20%" tone="blue" /><Kpi title="Cathay business impact" value={formatCurrency(cathayImpact)} detail="Expected contribution impact · simulated" tone="warning" /><Kpi title="Potential loss avoidable" value={formatCurrency(calculatePotentialLossAvoidable())} detail="Scenario-derived intervention difference" tone="success" /></section><OffloadTrendChart /><section className="overview-main-grid"><section className="panel"><div className="panel-heading"><div><h2>Flights ranked by expected loss</h2><p>Expected shipment loss is the prioritisation signal; probability, capacity and causal drivers remain visible.</p></div><DemoTag /></div><div className="table-wrap"><table><thead><tr><th>FLIGHT / ROUTE</th><th>DEMO OFFLOAD RISK SCORE</th><th>EXPECTED SHIPMENT RATE</th><th>CAPACITY SHORTFALL</th><th>ESTIMATED IMPACT</th><th>RISK DRIVERS</th></tr></thead><tbody>{rankedFlights.map((flight) => <tr key={flight.flightId} onClick={() => onSelectFlight(flight)}><td><strong>{flight.flightId}</strong><small>{flight.route} · {flight.departure}</small></td><td><strong>{Math.round(flight.forecastOffloadProbability * 100)}%</strong><small>{flight.forecastConfidence}% confidence</small></td><td>{Math.round(flight.predictedOffloadRate * 100)}%<small>{flight.affectedShipments} affected</small></td><td>{flight.forecastCapacityShortfall ? formatKg(flight.forecastCapacityShortfall) : 'None'}</td><td><b>{formatCurrency(flight.valueAtRisk)}</b><small>expected loss proxy</small></td><td>{flight.weatherRiskDrivers.join(', ')}<small>{flight.expectedOperationalImpact}</small></td></tr>)}</tbody></table></div></section><section className="panel alerts-panel"><div className="panel-heading"><div><h2>Fuel and weather alerts <span className="count-badge">{weatherAlerts.length}</span></h2><p>Supported pathways only. Weather exposure is not automatically an offload.</p></div><DemoTag /></div><div className="alert-list">{weatherAlerts.map((flight) => <article className={`alert-item ${flight.weatherRiskLevel.toLowerCase()}`} key={flight.flightId}><div className="alert-icon"><Icon name="alert" size={16} /></div><div className="alert-copy"><div className="alert-meta"><span>{flight.forecastAdditionalFuelWeight > 0 ? 'Fuel estimate changed' : 'Weather exposure'}</span><time>{flight.forecastConfidence}% confidence</time></div><strong>{flight.flightId}: {flight.forecastAdditionalFuelWeight > 0 ? `+${formatKg(flight.forecastAdditionalFuelWeight)} fuel may reduce payload by ${formatKg(flight.forecastCapacityShortfall)}` : `${flight.weatherRiskDrivers[0]} may affect ${flight.weatherRiskLevel === 'Low' ? 'operations' : 'handling'}`}</strong><small>{flight.route} · {flight.affectedShipments} shipment(s) · {formatCurrency(flight.valueAtRisk)} expected impact</small><p>{flight.expectedOperationalImpact}</p><button onClick={() => onSelectFlight(flight)}>Review prediction <Icon name="arrow" size={13} /></button></div></article>)}</div></section></section><section className="panel"><div className="panel-heading"><div><h2>Action queue</h2><p>Every item has an owner, urgency, reason, recommended action and current status.</p></div><DemoTag /></div><div className="action-queue"><article><div><strong>Capacity decision · {topFlight.flightId}</strong><small>Owner: {ownerForFlight(topFlight)} · Urgency: Immediate · Status: Open</small><p>{topFlight.forecastCapacityShortfall ? `${formatKg(topFlight.forecastCapacityShortfall)} shortfall and ${Math.round(topFlight.forecastOffloadProbability * 100)}% flight risk` : 'Highest expected loss in the current forecast population'}</p></div><button className="text-button" onClick={() => onSelectFlight(topFlight)}>Review Prediction <Icon name="arrow" size={14} /></button></article><article><div><strong>Shipment protection · {highestRiskShipment.id}</strong><small>Owner: Customer recovery · Urgency: High · Status: Needs review</small><p>{highestRiskShipment.riskDrivers.join(', ')}. Recovery availability: {highestRiskShipment.recoveryAvailable ? 'candidate found' : 'unavailable'}.</p></div><button className="text-button" onClick={() => onSelectShipment(highestRiskShipment)}>Review Shipment <Icon name="arrow" size={14} /></button></article><article><div><strong>Recovery pathway · {recoveryOptions[0].shipmentId}</strong><small>Owner: Network recovery · Urgency: High · Status: Candidate</small><p>{recoveryOptions[0].explanation}</p></div><button className="text-button" onClick={() => onNavigate('Recovery Plans')}>Review Recovery Plan <Icon name="arrow" size={14} /></button></article></div></section><footer>All records, forecasts, weather observations, and financial estimates are fictional simulated data. Approved payload calculations and live operational feeds are pending backend integration.</footer></main></div>
}

export function LegacyOverviewWorkspacePage({ onNavigate, onSelectFlight, onSelectShipment }: { onNavigate: (item: NavItem) => void; onSelectFlight: (flight: FlightCapacityForecast) => void; onSelectShipment: (shipment: Shipment) => void }) {
  const [reportWindow, setReportWindow] = useState<'24h' | '48h' | '7d'>('24h')
  const allForecasts = useMemo(() => buildForecasts(), [])
  const forecasts = reportWindow === '24h' ? allForecasts.slice(0, 3) : allForecasts
  const exposedShipments = shipments.filter((shipment) => forecasts.some((flight) => flight.flightId === shipment.flightId) && shipment.offloadProbability >= .2)
  const cathayImpact = forecasts.reduce((sum, flight) => sum + shipments.filter((shipment) => shipment.flightId === flight.flightId).reduce((shipmentSum, shipment) => shipmentSum + shipment.cathayImpact * shipment.offloadProbability, 0), 0)
  const avoidableLoss = Math.round(cathayImpact * .34)
  const predictedRate = aggregateForecastOffloadRate(forecasts)
  const fuelWeatherFlights = forecasts.filter((flight) => flight.forecastAdditionalFuelWeight > 0 || flight.weatherRiskLevel !== 'Low')
  return <div className="app-shell"><WorkspaceSidebar active="Overview" onNavigate={onNavigate} /><main className="main-content overview-page"><header className="topbar"><div className="crumb">CATHAY ROUTER <span>/</span> OVERVIEW</div><div className="top-actions"><span className="data-freshness"><span className="live-dot" />Updated 09:10 UTC</span><DemoTag /></div></header><div className="page-heading"><div><h1>Operations Overview</h1><p className="subtitle">Prioritise the decisions that protect capacity, customers, and Cathay value.</p></div><div className="report-controls"><span>Reporting window</span>{([['24h', 'Next 24h'], ['48h', 'Next 48h'], ['7d', 'Next 7d']] as const).map(([key, label]) => <button key={key} className={reportWindow === key ? 'selected' : ''} onClick={() => setReportWindow(key)}>{label}</button>)}</div></div><section className="kpi-grid overview-kpis"><Kpi title="Actual offload rate" value={`${Math.round((demoOffloadMetrics.actualOffloadRate ?? 0) * 1000) / 10}%`} detail={`${demoOffloadMetrics.actualOffloadedShipments} offloaded / ${demoOffloadMetrics.eligibleShipments} eligible · ${demoOffloadMetrics.reportingPeriod.label}`} tone="neutral" /><Kpi title="Predicted offload rate" value={predictedRate === null ? 'Unavailable' : `${Math.round(predictedRate * 1000) / 10}%`} detail={`${forecasts.length} flights · forecast population updates with window`} tone="warning" /><Kpi title="Flights high / critical risk" value={`${forecasts.filter((flight) => flight.forecastOffloadProbability >= .25).length}`} detail={`${forecasts.length} upcoming flights assessed`} tone="danger" /><Kpi title="Unique shipments at risk" value={`${exposedShipments.length}`} detail="Elevated offload or delay exposure" tone="blue" /><Kpi title="Cathay business impact" value={formatCurrency(cathayImpact)} detail="Expected contribution impact · simulated" tone="warning" /><Kpi title="Potential loss avoidable" value={formatCurrency(avoidableLoss)} detail="Feasible intervention scenario · illustrative" tone="success" /></section><section className="overview-trend panel"><div className="panel-heading"><div><h2>Actual versus predicted offload trend</h2><p>Actual outcomes and forecast rates are shown separately. Reporting period: {demoOffloadMetrics.reportingPeriod.label}.</p></div><DemoTag /></div><div className="trend-chart"><div className="trend-axis"><span>10%</span><span>5%</span><span>0%</span></div><div className="trend-bars">{demoOutcomes.map((outcome) => <div className="trend-column" key={outcome.flightId}><div className="bar-pair"><span className="trend-bar predicted" style={{ height: `${Math.max(5, outcome.predictedRate * 100 * 7)}px` }} title={`Predicted ${Math.round(outcome.predictedRate * 100)}%`} /><span className="trend-bar actual" style={{ height: `${Math.max(5, outcome.actualRate * 100 * 7)}px` }} title={`Actual ${Math.round(outcome.actualRate * 100)}%`} /></div><small>{outcome.flightId}</small></div>)}</div><div className="trend-legend"><span><i className="predicted-key" />Predicted</span><span><i className="actual-key" />Actual</span></div></div></section><section className="overview-main-grid"><section className="panel"><div className="panel-heading"><div><h2>Highest-risk upcoming flights</h2><p>Sorted by expected business impact. Select a flight for its forecast details.</p></div><button className="text-button" onClick={() => onNavigate('Predictions')}>Open Predictions <Icon name="arrow" size={14} /></button></div><div className="table-wrap"><table className="overview-flight-table"><thead><tr><th>FLIGHT / ROUTE</th><th>PAYLOAD</th><th>OFFLOAD METRICS</th><th>BUSINESS IMPACT</th><th>RISK DRIVERS</th></tr></thead><tbody>{[...forecasts].sort((a, b) => b.valueAtRisk - a.valueAtRisk).map((flight) => <tr key={flight.flightId} onClick={() => onSelectFlight(flight)}><td><strong>{flight.flightId}</strong><small>{flight.route} · {flight.departure}<br />{flight.aircraftType}</small></td><td><b>{formatKg(flight.forecastCargoCapacity)}</b><small>{flight.forecastCapacityShortfall ? `${formatKg(flight.forecastCapacityShortfall)} shortfall` : 'No shortfall'}</small></td><td><strong>{Math.round(flight.forecastOffloadProbability * 100)}% probability</strong><small>{Math.round(flight.predictedOffloadRate * 100)}% shipment rate · {flight.affectedShipments} affected</small></td><td><b>{formatCurrency(flight.valueAtRisk)}</b><small>Updated {flight.fuelEstimateTimestamp}</small></td><td><RiskBadge level={flight.weatherRiskLevel} /><small>{flight.weatherRiskDrivers.join(', ')}</small></td></tr>)}</tbody></table></div></section><section className="panel exposure-panel"><div className="panel-heading"><div><h2>Fuel and weather exposure</h2><p>Supported pathways only; exposure is not automatically an offload.</p></div><DemoTag /></div><div className="exposure-list">{fuelWeatherFlights.map((flight) => <article key={flight.flightId}><div><strong>{flight.flightId} · {flight.weatherRiskDrivers[0]}</strong><small>{flight.expectedOperationalImpact}</small></div><b>{flight.forecastAdditionalFuelWeight ? `+${formatKg(flight.forecastAdditionalFuelWeight)}` : 'Handling / route'}</b><small>{flight.affectedShipments} shipments · {formatCurrency(flight.valueAtRisk)} at risk</small></article>)}</div></section></section><section className="overview-lower-grid"><section className="panel value-summary"><div className="panel-heading"><div><h2>Shipment value at risk</h2><p>{exposedShipments.length} unique shipments · ranked by expected consequence, not declared value.</p></div><button className="text-button" onClick={() => onNavigate('Shipments')}>Open Shipments <Icon name="arrow" size={14} /></button></div><div className="value-summary-list">{[...exposedShipments].sort((a, b) => assessShipmentValue(b).latestScenarioLoss - assessShipmentValue(a).latestScenarioLoss).slice(0, 3).map((shipment) => { const value = assessShipmentValue(shipment); return <article key={shipment.id} onClick={() => onSelectShipment(shipment)}><div><strong>{shipment.id} · {shipment.customer}</strong><small>{shipment.category} · {shipment.deadline}</small></div><b>{formatCurrency(value.latestScenarioLoss)}</b><small>{Math.round(shipment.offloadProbability * 100)}% offload probability · {shipment.recoveryAvailable ? 'Alternative available' : 'No alternative found'}</small></article> })}</div></section><section className="panel action-panel"><div className="panel-heading"><div><h2>Prioritized action queue</h2><p>Human review required; no action is marked completed.</p></div></div><div className="action-list">{fuelWeatherFlights.slice(0, 3).map((flight, index) => <article key={flight.flightId}><span className="action-index">{String(index + 1).padStart(2, '0')}</span><div><strong>{flight.forecastCapacityShortfall ? `Review ${flight.flightId} allocation` : `Re-evaluate ${flight.flightId} weather exposure`}</strong><p>{flight.forecastCapacityShortfall ? `${formatKg(flight.forecastCapacityShortfall)} capacity shortfall may expose ${flight.affectedShipments} shipments.` : flight.expectedOperationalImpact}</p><small>Decision before {flight.departure} · status: Awaiting review</small></div></article>)}</div></section></section><section className="overview-activity panel"><div className="panel-heading"><div><h2>Network activity and outcomes</h2><p>Compact operational context; detailed optimization remains in Recovery Plans.</p></div><button className="text-button" onClick={() => onNavigate('Recovery Plans')}>Open Recovery Plans <Icon name="arrow" size={14} /></button></div><div className="activity-summary"><span><b>{recoveryOptions.length}</b><small>Recovery plans awaiting review</small></span><span><b>{demoOutcomes.filter((outcome) => outcome.interventionApplied).length}</b><small>Preventive actions recorded</small></span><span><b>{demoOutcomes.filter((outcome) => outcome.actualOffload).length}</b><small>Recorded offload outcomes</small></span><span><b>{forecasts.filter((flight) => flight.forecastCapacityShortfall > 0).length}</b><small>Flights with capacity shortfall</small></span></div></section><footer>All records, forecasts, weather observations, and financial estimates are fictional simulated data. Latest data update: 16 Oct 2026 09:10 UTC.</footer></main></div>
}

function FlightDrawer({ flight, onClose, onOpenPreventionPlan }: { flight: FlightCapacityForecast; onClose: () => void; onOpenPreventionPlan: (flightId: string) => void }) { const weather = getWeather(flight.flightId); const affected = shipments.filter((shipment) => shipment.flightId === flight.flightId); return <Drawer onClose={onClose} eyebrow="FLIGHT FORECAST · SIMULATED" title={`${flight.flightId} · ${flight.route}`}><RiskBadge level={flight.weatherRiskLevel} /><div className="impact-grid"><div><small>ORIGINAL CAPACITY</small><b>{formatKg(flight.originalCargoCapacity)}</b></div><div><small>CURRENT CAPACITY</small><b>{formatKg(flight.forecastCargoCapacity)}</b></div><div><small>FUEL CHANGE</small><b className={flight.forecastAdditionalFuelWeight ? 'fuel-up' : ''}>{flight.forecastAdditionalFuelWeight ? `+${formatKg(flight.forecastAdditionalFuelWeight)}` : 'None'}</b></div><div><small>DEMO OFFLOAD RISK SCORE</small><b>{Math.round(flight.forecastOffloadProbability * 100)}%</b></div></div><h3>Risk factors</h3><ul className="driver-list">{flight.riskDrivers.map((driver) => <li key={driver}>{driver}</li>)}</ul><h3>Risk pathway</h3><div className="pathway"><span>Weather deterioration</span><Icon name="arrow" size={14} /><span>Fuel requirement +{formatKg(flight.forecastAdditionalFuelWeight)}</span><Icon name="arrow" size={14} /><span>Payload {flight.forecastCapacityShortfall ? 'shortfall predicted' : 'still sufficient'}</span></div><dl><div><dt>Weather exposure</dt><dd>{weather.weatherCondition} · {weather.pathway}</dd></div><div><dt>Operational consequence</dt><dd>{flight.expectedOperationalImpact}</dd></div><div><dt>Shipments affected</dt><dd>{affected.length ? affected.map((shipment) => shipment.id).join(', ') : 'None identified'}</dd></div><div><dt>Estimated loss without intervention</dt><dd>{formatCurrency(flight.valueAtRisk)}</dd></div><div><dt>Data freshness</dt><dd>{flight.fuelEstimateTimestamp} · {flight.forecastConfidence}% confidence</dd></div></dl><div className="drawer-note"><Icon name="alert" size={17} /><span>Safety fuel is an approved operational constraint and is never reduced to preserve cargo. Payload is illustrative until connected to an authoritative capacity service.</span></div><button className="apply-button" onClick={() => onOpenPreventionPlan(flight.flightId)}>Open Prevention Plan <small>Compare early options</small></button></Drawer> }

export function LegacyShipmentDrawer({ shipment, onClose }: { shipment: Shipment; onClose: () => void }) { return <Drawer onClose={onClose} eyebrow="SHIPMENT DETAIL · SIMULATED" title={shipment.id}><RiskBadge level={shipment.offloadProbability > .75 ? 'Critical' : 'High'} /><p className="drawer-subtitle">{shipment.customer} · {shipment.category}</p><div className="impact-grid"><div><small>DEMO OFFLOAD RISK SCORE</small><b>{Math.round(shipment.offloadProbability * 100)}%</b></div><div><small>EXPECTED DELAY</small><b>{shipment.estimatedDelayHours}h</b></div><div><small>CARGO IMPACT</small><b>{formatCurrency(shipment.cargoImpact)}</b></div><div><small>EST. CATHAY CONTRIBUTION LOSS</small><b>{formatCurrency(shipment.cathayImpact)}</b></div></div><h3>Why this shipment is prioritised</h3><ul className="driver-list">{shipment.riskDrivers.map((driver) => <li key={driver}>{driver}</li>)}</ul><dl><div><dt>Planned movement</dt><dd>{shipment.flightId} · {shipment.origin} → {shipment.destination}</dd></div><div><dt>Delivery deadline</dt><dd>{shipment.deadline}</dd></div><div><dt>Recovery availability</dt><dd>{shipment.recoveryAvailable ? 'Candidate alternatives available' : 'No suitable alternative found'}</dd></div><div><dt>Loss assumption</dt><dd>Category and delay-based estimate; declared value is not treated as actual loss.</dd></div></dl><div className="drawer-note"><Icon name="box" size={17} /><span>Estimate range and customer terms require backend commercial data. Current values are illustrative.</span></div></Drawer> }

function ShipmentDrawer({ shipment, onClose, onSelectCustomer }: { shipment: Shipment; onClose: () => void; onSelectCustomer?: (profile: CustomerValueProfile) => void }) { const profile = customerProfiles.find((item) => item.customer === shipment.customer); return <Drawer onClose={onClose} eyebrow="SHIPMENT DETAIL · SIMULATED" title={shipment.id}><RiskBadge level={shipment.offloadProbability > .75 ? 'Critical' : 'High'} /><p className="drawer-subtitle">{shipment.customer} · {shipment.category}</p>{profile && onSelectCustomer && <button className="text-button" onClick={() => onSelectCustomer(profile)}>Open customer profile <Icon name="arrow" size={14} /></button>}<div className="impact-grid"><div><small>DEMO OFFLOAD RISK SCORE</small><b>{Math.round(shipment.offloadProbability * 100)}%</b></div><div><small>EXPECTED DELAY</small><b>{shipment.estimatedDelayHours}h</b></div><div><small>CARGO IMPACT</small><b>{formatCurrency(shipment.cargoImpact)}</b></div><div><small>EST. CATHAY CONTRIBUTION LOSS</small><b>{formatCurrency(shipment.cathayImpact)}</b></div></div><h3>Why this shipment is prioritised</h3><ul className="driver-list">{shipment.riskDrivers.map((driver) => <li key={driver}>{driver}</li>)}</ul><dl><div><dt>Planned movement</dt><dd>{shipment.flightId} · {shipment.origin} → {shipment.destination}</dd></div><div><dt>Delivery deadline</dt><dd>{shipment.deadline}</dd></div><div><dt>Recovery availability</dt><dd>{shipment.recoveryAvailable ? 'Candidate alternatives available' : 'No suitable alternative found'}</dd></div><div><dt>Loss assumption</dt><dd>Category and delay-based estimate; declared value is not treated as actual loss.</dd></div></dl><div className="drawer-note"><Icon name="box" size={17} /><span>Estimate range and customer terms require backend commercial data. Current values are illustrative.</span></div></Drawer> }

function Drawer({ eyebrow, title, onClose, children }: { eyebrow: string; title: string; onClose: () => void; children: ReactNode }) { return <div className="modal-backdrop" onClick={onClose}><aside className="detail-drawer" onClick={(event) => event.stopPropagation()}><button className="close-button" onClick={onClose} aria-label="Close details"><Icon name="close" /></button><p className="eyebrow">{eyebrow}</p><h2>{title}</h2>{children}</aside></div> }

function RecoveryDrawer({ option, scenario = 'recover', onClose }: { option: RecoveryOption; scenario?: 'no-intervention' | 'preventive' | 'recover'; onClose: () => void }) { const evaluation = evaluateRecoveryScenario(scenario).find((item) => item.option.id === option.id)!; const [decision, setDecision] = useState('Pending review'); const explanation = explainRecoveryEvaluation(evaluation); return <Drawer onClose={onClose} eyebrow="RECOVERY PLAN · SIMULATED" title={option.shipmentId}><div className="route-comparison drawer-route"><b>{option.original}</b><Icon name="arrow" /><b>{option.alternative}</b></div><div className={`optimization-status ${evaluation.isFeasible ? 'feasible' : 'rejected'}`}><strong>{evaluation.optimizationStatus}</strong><small>{evaluation.terminationReason}</small></div><div className="impact-card"><span>TOTAL MODELED EXPECTED LOSS</span><strong>{formatCurrency(evaluation.costBreakdown.totalExpectedLoss)}</strong><small>{evaluation.option.feasibility}% feasible · {evaluation.option.capacityStatus} · optimality gap {evaluation.optimalityGap ?? 'unknown'}</small></div><h3>Why this plan?</h3><ul className="explanation-list">{explanation.map((reason) => <li key={reason}>{reason}</li>)}</ul><h3>Cost breakdown</h3><dl><div><dt>Cargo and customer impact</dt><dd>{formatCurrency(evaluation.costBreakdown.cargoCustomerImpact)}</dd></div><div><dt>Cathay contribution impact</dt><dd>{formatCurrency(evaluation.costBreakdown.cathayContributionImpact)}</dd></div><div><dt>Recovery and handling</dt><dd>{formatCurrency(evaluation.costBreakdown.recoveryAndHandlingCost)}</dd></div><div><dt>Delay and service impact</dt><dd>{formatCurrency(evaluation.costBreakdown.delayAndServiceImpact)}</dd></div><div><dt>Network impact</dt><dd>{formatCurrency(evaluation.costBreakdown.downstreamNetworkImpact)}</dd></div></dl><h3>Evidence and trade-offs</h3><dl><div><dt>Hard constraints</dt><dd>{evaluation.hardConstraints.join(' ')}</dd></div><div><dt>Alternatives considered</dt><dd>{evaluation.alternativesConsidered.join(', ') || 'None'}</dd></div><div><dt>Rejected alternatives</dt><dd>{evaluation.rejectedReasons.join(' ') || 'None for this candidate'}</dd></div><div><dt>Uncertainty</dt><dd>{evaluation.missingData.join(' ') || 'No missing inputs recorded'} {evaluation.assumptions.join(' ')}</dd></div><div><dt>Evidence version</dt><dd>{evaluation.recommendationVersion} · predicted {evaluation.predictionTimestamp} · optimized {evaluation.optimizationTimestamp}</dd></div></dl><div className="decision-controls"><strong>Human decision: {decision}</strong><div><button onClick={() => setDecision('Approved for operational review')}>Approve review</button><button onClick={() => setDecision('Rejected / override recorded')}>Reject / override</button></div><small>Demo trace only. No cargo is reassigned or capacity reserved.</small></div></Drawer> }

export function LegacyDisruptionsWorkspacePage({ onNavigate, onSelectFlight }: { onNavigate: (item: NavItem) => void; onSelectFlight: (flight: FlightCapacityForecast) => void }) {
  const forecasts = useMemo(() => buildForecasts(), [])
  const disruptions = weatherAssessments.filter((weather) => weather.severity !== 'Low')
  return <div className="app-shell"><WorkspaceSidebar active="Overview" onNavigate={onNavigate} /><main className="main-content shipment-page"><header className="topbar"><div className="crumb">CATHAY ROUTER <span>/</span> DISRUPTION EVIDENCE</div><DemoTag /></header><div className="page-heading"><div><p className="eyebrow">LEGACY COMPATIBILITY VIEW · DEMO DATA</p><h1>Disruption Evidence</h1><p className="subtitle">This view is retained for compatibility; operational disruption evidence is surfaced through Overview, Predictions and Recovery Plans.</p></div><DemoTag /></div><section className="panel"><div className="panel-heading"><div><h2>Confirmed and forecast evidence</h2><p>Use the primary workspaces for action and human review.</p></div></div><div className="table-wrap"><table><thead><tr><th>FLIGHT / SEGMENT</th><th>CONDITION</th><th>PATHWAY</th><th>IMPACT</th><th>DATA STATUS</th><th /></tr></thead><tbody>{disruptions.map((weather) => { const forecast = forecasts.find((item) => item.flightId === weather.flightId); return <tr key={weather.flightId} onClick={() => forecast && onSelectFlight(forecast)}><td><strong>{weather.flightId}</strong><small>{weather.locationOrRouteSegment}</small></td><td><RiskBadge level={weather.severity} /><small>{weather.weatherCondition}</small></td><td>{weather.pathway}</td><td>{weather.estimatedOperationalImpact}</td><td>{weather.dataAvailability}</td><td><button className="row-action" aria-label={`Review ${weather.flightId}`}><Icon name="arrow" size={15} /></button></td></tr> })}</tbody></table></div></section></main></div>
}

function SettingsWorkspacePage({ onNavigate }: { onNavigate: (item: NavItem) => void }) {
  const [thresholds, setThresholds] = useState({ low: 0.1, moderate: 0.25, high: 0.5 })
  const [effectiveDate, setEffectiveDate] = useState('2026-10-16')
  const [horizon, setHorizon] = useState('24')
  const [leadTime, setLeadTime] = useState('24')
  const [currency, setCurrency] = useState('USD')
  const [weightUnit, setWeightUnit] = useState('kg')
  const [timezone, setTimezone] = useState('UTC')
  const [alertsEnabled, setAlertsEnabled] = useState(true)
  const [saved, setSaved] = useState(false)
  const saveSettings = () => setSaved(true)
  const updateThreshold = (key: keyof typeof thresholds, value: string) => { setSaved(false); setThresholds((current) => ({ ...current, [key]: Math.min(1, Math.max(0, Number(value) / 100)) })) }
  return <div className="app-shell"><WorkspaceSidebar active="Settings" onNavigate={onNavigate} /><main className="main-content shipment-page"><header className="topbar"><div className="crumb">CATHAY ROUTER <span>/</span> SETTINGS</div><DemoTag /></header><div className="page-heading"><div><p className="eyebrow">WORKSPACE CONFIGURATION · DEMO DATA</p><h1>Settings</h1><p className="subtitle">Configure decision-support preferences while protecting mandatory operational constraints.</p></div><DemoTag /></div><section className="analytics-note"><strong>Demo configuration</strong><span>Changes are session-local. Production authorization, audit storage and live integrations are unavailable.</span><small>Required fuel, aircraft safety, cargo-handling and compatibility constraints cannot be weakened here.</small></section><section className="settings-grid"><section className="panel"><div className="panel-heading"><div><h2>Risk thresholds</h2><p>Business triage bands, not approved Cathay service levels.</p></div></div><div className="settings-form"><label>Low to Moderate (%)<input type="number" min="0" max="100" value={Math.round(thresholds.low * 100)} onChange={(event) => updateThreshold('low', event.target.value)} /></label><label>Moderate to High (%)<input type="number" min="0" max="100" value={Math.round(thresholds.moderate * 100)} onChange={(event) => updateThreshold('moderate', event.target.value)} /></label><label>High to Critical (%)<input type="number" min="0" max="100" value={Math.round(thresholds.high * 100)} onChange={(event) => updateThreshold('high', event.target.value)} /></label><label>Effective date<input type="date" value={effectiveDate} onChange={(event) => { setSaved(false); setEffectiveDate(event.target.value) }} /></label><div className="analytics-note"><strong>Version 1.1</strong><span>Current session draft · last published 2026-10-15 by Operations Policy</span></div></div></section><section className="panel"><div className="panel-heading"><div><h2>Forecast settings</h2><p>Controls saved snapshot scope and forecast horizon.</p></div></div><div className="settings-form"><label>Forecast horizon (hours)<input type="number" min="1" max="168" value={horizon} onChange={(event) => { setSaved(false); setHorizon(event.target.value) }} /></label><label>Historical snapshot lead time (hours)<input type="number" min="1" max="72" value={leadTime} onChange={(event) => { setSaved(false); setLeadTime(event.target.value) }} /></label><small>Current saved cohort fixtures use a 24-hour lead time. This does not reconstruct forecasts after departure.</small></div></section><section className="panel"><div className="panel-heading"><div><h2>Optimization objectives</h2><p>Business preferences are separate from non-negotiable constraints.</p></div></div><div className="settings-form"><label>Expected loss priority (%)<input type="number" value="40" readOnly /></label><label>Delay and service priority (%)<input type="number" value="25" readOnly /></label><label>Recovery cost priority (%)<input type="number" value="20" readOnly /></label><label>Network impact priority (%)<input type="number" value="15" readOnly /></label><div className="analytics-note"><strong>Mandatory constraints locked</strong><span>Safety fuel, aircraft limits, cargo compatibility, connection confirmation and approved handling requirements cannot be relaxed by ordinary settings.</span></div></div></section><section className="panel"><div className="panel-heading"><div><h2>Alert settings</h2><p>Configure notification intent without implying a live escalation channel.</p></div></div><div className="settings-form"><label className="checkbox-row"><input type="checkbox" checked={alertsEnabled} onChange={(event) => { setSaved(false); setAlertsEnabled(event.target.checked) }} /> Enable simulated alerts</label><label>Recipients<select><option>Network operations</option><option>Load planning</option><option>Customer recovery</option></select></label><label>Escalation<select><option>Review in workspace</option><option>Unavailable in demo</option></select></label></div></section><section className="panel"><div className="panel-heading"><div><h2>Units and reporting</h2><p>Presentation preferences only.</p></div></div><div className="settings-form"><label>Weight unit<select value={weightUnit} onChange={(event) => setWeightUnit(event.target.value)}><option>kg</option><option>lb</option></select></label><label>Currency<select value={currency} onChange={(event) => setCurrency(event.target.value)}><option>USD</option><option>HKD</option></select></label><label>Timezone<select value={timezone} onChange={(event) => setTimezone(event.target.value)}><option>UTC</option><option>Asia/Hong_Kong</option></select></label><span>Reporting windows remain cohort-defined until backend reporting configuration is connected.</span></div></section><section className="panel"><div className="panel-heading"><div><h2>Data integrations and provenance</h2><p>Read-only health and version information for this demo.</p></div></div><div className="table-wrap"><table><thead><tr><th>SOURCE</th><th>STATUS</th><th>LAST UPDATE</th><th>QUALITY</th></tr></thead><tbody>{[['Flight capacity', 'Simulated', '16 Oct 09:10 UTC', 'Illustrative'], ['Fuel estimates', 'Simulated', '16 Oct 09:10 UTC', 'Illustrative'], ['Weather', 'Partial', '16 Oct 09:10 UTC', 'CX289/CX880 partial'], ['Bookings and shipments', 'Simulated', '16 Oct 09:00 UTC', 'Demo records']].map(([source, status, update, quality]) => <tr key={source}><td><strong>{source}</strong></td><td>{status}</td><td>{update}</td><td>{quality}</td></tr>)}</tbody></table></div><div className="analytics-note"><strong>Model version:</strong><span>forecast-heuristic-v2 · cost-assumption-v1 · recovery-heuristic-v2</span><small>Recommendations display their evidence version in detail drawers.</small></div></section><section className="panel"><div className="panel-heading"><div><h2>Access and audit</h2><p>Authorization and audit storage are unavailable in the demo environment.</p></div></div><div className="empty-state"><strong>Read-only demo role</strong><span>Current operator: Alex Lee · Network operator. Setting changes are not published to production.</span><small>Last local draft: {saved ? 'just now' : 'not changed this session'} · Effective date: {effectiveDate}</small></div></section></section><div className="settings-actions"><button className="outline-button" onClick={saveSettings}>Save session preferences</button>{saved && <small role="status">Saved for this session only.</small>}</div></main></div>
}

export function LegacySettingsWorkspacePage({ onNavigate }: { onNavigate: (item: NavItem) => void }) {
  const [threshold, setThreshold] = useState('25')
  const [saved, setSaved] = useState(false)
  const [notifications, setNotifications] = useState(true)
  const saveSettings = () => setSaved(true)
  return <div className="app-shell"><WorkspaceSidebar active="Settings" onNavigate={onNavigate} /><main className="main-content shipment-page"><header className="topbar"><div className="crumb">CATHAY ROUTER <span>/</span> SETTINGS</div><DemoTag /></header><div className="page-heading"><div><p className="eyebrow">WORKSPACE CONFIGURATION · DEMO DATA</p><h1>Settings</h1><p className="subtitle">Control local decision-support preferences without implying changes to live operations.</p></div><DemoTag /></div><section className="panel settings-panel"><div className="panel-heading"><div><h2>Forecast preferences</h2><p>These settings affect this demo workspace only.</p></div></div><div className="settings-form"><label>High-risk threshold (%)<input type="number" min="0" max="100" value={threshold} onChange={(event) => { setSaved(false); setThreshold(event.target.value) }} /></label><label className="checkbox-row"><input type="checkbox" checked={notifications} onChange={(event) => { setSaved(false); setNotifications(event.target.checked) }} /> Show simulated operational alerts</label><div className="settings-actions"><button className="outline-button" onClick={saveSettings}>Save preferences</button>{saved && <small role="status">Saved for this session.</small>}</div></div></section><section className="panel"><div className="panel-heading"><div><h2>Data connections</h2><p>Live integrations are unavailable in this demo environment.</p></div></div><div className="empty-state"><strong>Unavailable</strong><span>Operational flight, shipment, weather, and solver services are not connected.</span></div></section></main></div>
}

function CustomerProfileDrawer({ profile, onClose, onSelectShipment }: { profile: CustomerValueProfile; onClose: () => void; onSelectShipment: (shipment: Shipment) => void }) {
  const profileShipments = shipments.filter((shipment) => shipment.customer === profile.customer)
  return <Drawer onClose={onClose} eyebrow="CUSTOMER PROFILE · SIMULATED" title={profile.customer}><span className="demo-label">{profile.segment}</span><div className="impact-grid"><div><small>SHIPMENTS AT RISK</small><b>{profile.currentShipmentsAtRisk}</b></div><div><small>CURRENT IMPACT</small><b>{formatCurrency(profile.currentValueAtRisk)}</b></div><div><small>HISTORICAL REVENUE</small><b>{formatCurrency(profile.historicalRevenue)}</b></div><div><small>HISTORICAL OFFLOAD</small><b>{(profile.historicalOffloadRate * 100).toFixed(1)}%</b></div></div><h3>Service context</h3><dl><div><dt>Service commitment</dt><dd>{profile.serviceCommitment}</dd></div><div><dt>Handling requirements</dt><dd>{profile.handlingRequirements}</dd></div><div><dt>Commercial uncertainty</dt><dd>Contract terms, realised claims and customer revenue attribution are unavailable in this demo.</dd></div></dl><h3>Customer shipments</h3><ul className="driver-list">{profileShipments.map((shipment) => <li key={shipment.id}><button className="text-button" onClick={() => onSelectShipment(shipment)}>{shipment.id} · {Math.round(shipment.offloadProbability * 100)}% offload risk <Icon name="arrow" size={13} /></button></li>)}</ul></Drawer>
}

function App() {
  void RecoveryWorkspacePage
  const [activeNav, setActiveNav] = useState<NavItem>('Overview')
  const [query, setQuery] = useState('')
  const [sort, setSort] = useState<'risk' | 'payload' | 'value'>('risk')
  const [menuOpen, setMenuOpen] = useState(false)
  const [selectedFlight, setSelectedFlight] = useState<FlightCapacityForecast | null>(null)
  const [selectedShipment, setSelectedShipment] = useState<Shipment | null>(null)
  const [selectedCustomer, setSelectedCustomer] = useState<CustomerValueProfile | null>(null)
  const [selectedRecovery, setSelectedRecovery] = useState<RecoveryOption | null>(null)
  const [selectedRecoveryCaseId, setSelectedRecoveryCaseId] = useState<string | undefined>(undefined)
  const [selectedPreventiveFlightId, setSelectedPreventiveFlightId] = useState<string | undefined>(undefined)
  const [selectedRecoveryScenario, setSelectedRecoveryScenario] = useState<'no-intervention' | 'preventive' | 'recover'>('recover')
  const clearDrawers = () => {
    setSelectedFlight(null)
    setSelectedShipment(null)
    setSelectedCustomer(null)
    setSelectedRecovery(null)
    setSelectedRecoveryCaseId(undefined)
    setSelectedPreventiveFlightId(undefined)
  }
  const navigateTo = (item: NavItem) => {
    setActiveNav(item)
    clearDrawers()
  }
  const openFlight = (flight: FlightCapacityForecast) => {
    clearDrawers()
    setSelectedFlight(flight)
    setActiveNav('Predictions')
  }
  const openRecoveryCase = (caseId: string) => {
    clearDrawers()
    setSelectedRecoveryCaseId(caseId)
    setActiveNav('Recovery Plans')
  }
  const openPreventionPlan = (flightId?: string) => {
    clearDrawers()
    setSelectedPreventiveFlightId(flightId)
    setActiveNav('Prevention Plan')
  }
  const openShipment = (shipment: Shipment) => {
    clearDrawers()
    setSelectedShipment(shipment)
    setActiveNav('Shipments')
  }
  const openShipmentId = (shipmentId: string) => {
    const known = shipments.find((shipment) => shipment.id === shipmentId)
    if (known) {
      openShipment(known)
      return
    }
    const recoveryCase = recoveryCases.find((item) => item.affectedShipmentIds.includes(shipmentId))
    if (!recoveryCase) return
    openShipment({
      id: shipmentId,
      customer: 'Recovery shipment',
      category: 'Cargo details pending',
      origin: recoveryCase.origin,
      destination: recoveryCase.destination,
      flightId: recoveryCase.originalFlight,
      weightKg: 0,
      volumeM3: 0,
      priority: 'High',
      deadline: recoveryCase.deliveryCommitment,
      offloadProbability: 0,
      estimatedDelayHours: 0,
      cargoImpact: recoveryCase.baselineExpectedLoss,
      cathayImpact: 0,
      recoveryAvailable: true,
      riskDrivers: [recoveryCase.reason],
    })
  }
  const openCustomer = (profile: CustomerValueProfile) => {
    clearDrawers()
    setSelectedCustomer(profile)
  }
  const openRecovery = (option: RecoveryOption, scenario: 'no-intervention' | 'preventive' | 'recover' = 'recover') => {
    clearDrawers()
    setSelectedRecovery(option)
    setSelectedRecoveryScenario(scenario)
  }
  const forecasts = useMemo(() => buildForecasts(), [])
  const filteredForecasts = useMemo(() => [...forecasts].filter((flight) => `${flight.flightId} ${flight.route}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sort === 'payload' ? b.forecastCapacityShortfall - a.forecastCapacityShortfall : sort === 'value' ? b.valueAtRisk - a.valueAtRisk : b.forecastOffloadProbability - a.forecastOffloadProbability), [forecasts, query, sort])
  const fuelRisk = forecasts.filter((flight) => flight.forecastAdditionalFuelWeight > 0 && flight.forecastCapacityShortfall > 0).length
  const weatherExposed = forecasts.filter((flight) => flight.weatherRiskLevel !== 'Low').length
  const valueAtRisk = forecasts.reduce((total, flight) => total + flight.valueAtRisk, 0)
  const navItems: [string, string][] = [['Overview', 'grid'], ['Predictions', 'chart'], ['Prevention Plan', 'route'], ['Shipments', 'box'], ['Recovery Plans', 'route'], ['Analytics', 'chart'], ['Settings', 'settings']]
  const pageTitle = activeNav === 'Overview' ? 'Operations Overview' : activeNav
  if (activeNav === 'Overview') return <OverviewRenderBoundary onNavigate={navigateTo}><OverviewControlTower onNavigate={navigateTo} onSelectFlight={openFlight} onSelectPreventiveFlight={openPreventionPlan} onSelectRecoveryCase={openRecoveryCase} onSelectShipment={openShipmentId} /></OverviewRenderBoundary>
  if (activeNav === 'Shipments') return <><ShipmentWorkspacePage onNavigate={navigateTo} onSelect={openShipment} onSelectCustomer={openCustomer} />{selectedShipment && <ShipmentDrawer shipment={selectedShipment} onClose={() => setSelectedShipment(null)} onSelectCustomer={openCustomer} />}{selectedCustomer && <CustomerProfileDrawer profile={selectedCustomer} onClose={() => setSelectedCustomer(null)} onSelectShipment={openShipment} />}</>
  if (activeNav === 'Predictions') return <><PredictionWorkspacePage onNavigate={navigateTo} onSelectFlight={openFlight} />{selectedFlight && <FlightDrawer flight={selectedFlight} onClose={() => setSelectedFlight(null)} onOpenPreventionPlan={openPreventionPlan} />}{selectedShipment && <ShipmentDrawer shipment={selectedShipment} onClose={() => setSelectedShipment(null)} onSelectCustomer={openCustomer} />}</>
  if (activeNav === 'Prevention Plan') return <><PreventionPlanPage initialFlightId={selectedPreventiveFlightId} onNavigate={navigateTo} onSelectShipment={openShipmentId} onReview={(option) => openRecovery(option, 'preventive')} />{selectedRecovery && <RecoveryDecisionDrawer option={selectedRecovery} scenario="preventive" onClose={() => setSelectedRecovery(null)} />}</>
  if (activeNav === 'Recovery Plans') return <><RecoveryComparisonPage initialCaseId={selectedRecoveryCaseId} onNavigate={navigateTo} onSelect={openRecovery} onSelectShipment={openShipmentId} />{selectedRecovery && <RecoveryDecisionDrawer option={selectedRecovery} scenario={selectedRecoveryScenario} onClose={() => setSelectedRecovery(null)} />}</>
  if (activeNav === 'Analytics') return <AnalyticsWorkspacePage onNavigate={navigateTo} />
  if (activeNav === 'Settings') return <SettingsWorkspacePage onNavigate={navigateTo} />
  // @ts-expect-error Legacy fallback is unreachable after the explicit remaining routes above.
  return <div className="app-shell"><aside className={`sidebar ${menuOpen ? 'open' : ''}`}><div className="brand"><span className="brand-mark"><Icon name="plane" size={20} /></span><span>CARGO <b>RECOVERY</b></span></div><div className="nav-label">WORKSPACE</div><nav>{navItems.map(([label, icon]) => <button key={label} className={activeNav === label ? 'active' : ''} onClick={() => { setActiveNav(label); setMenuOpen(false) }}><Icon name={icon} /><span>{label}</span>{label === 'Disruptions' && <em>{weatherExposed}</em>}</button>)}</nav><div className="sidebar-footer"><div className="nav-label">OPERATIONS CONTROL</div><div className="demo-status"><span />Demo environment</div><div className="profile"><div className="avatar">AL</div><div><strong>Alex Lee</strong><small>Network operator</small></div></div></div></aside><main className="main-content"><header className="topbar"><button className="mobile-menu" onClick={() => setMenuOpen(!menuOpen)} aria-label="Toggle navigation"><span /><span /><span /></button><div className="crumb">CATHAY ROUTER <span>/</span> {activeNav.toUpperCase()}</div><div className="top-actions"><label className="global-search"><Icon name="search" size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search flight, shipment or route" aria-label="Search" /></label><button className="icon-button notification" aria-label="Notifications"><Icon name="bell" /><i /></button><div className="top-avatar">AL</div></div></header><div className="page-heading"><div><h1>{pageTitle}</h1><p className="subtitle">Fuel and weather-aware decision support for cargo capacity.</p></div><div className="header-badges"><DemoTag /><button className="outline-button"><Icon name="clock" size={16} /> Forecast window · 24h</button></div></div><section className="kpi-grid"><Kpi title="Actual offload rate" value="4.2%" detail="42 offloaded / 1,000 eligible · prior 24h" tone="neutral" /><Kpi title="Predicted offload rate" value="8.7%" detail="Forecast · 4 flights · 84% confidence" tone="warning" /><Kpi title="Fuel capacity at risk" value={`${fuelRisk} flights`} detail="Additional fuel may reduce payload" tone="danger" /><Kpi title="Weather-exposed flights" value={`${weatherExposed}`} detail="Exposure is not the same as offload" tone="blue" /><Kpi title="Fuel / weather value at risk" value={formatCurrency(valueAtRisk)} detail="Overlap handled once · illustrative" tone="warning" /></section><div className="content-grid"><div><div className="sort-strip"><span>Sort forecast by</span><button className={sort === 'risk' ? 'selected' : ''} onClick={() => setSort('risk')}>Offload probability</button><button className={sort === 'payload' ? 'selected' : ''} onClick={() => setSort('payload')}>Payload reduction</button><button className={sort === 'value' ? 'selected' : ''} onClick={() => setSort('value')}>Value at risk</button></div><ForecastTable forecasts={filteredForecasts} onSelect={setSelectedFlight} /><ShipmentTable onSelect={setSelectedShipment} /></div><div><Alerts onReview={setSelectedFlight} /><RecoveryPanel onSelect={setSelectedRecovery} /></div></div><section className="scenario-panel"><div><p className="eyebrow">SCENARIO COMPARISON · SIMULATED</p><h2>Prevent the shortfall before departure</h2><p>Baseline uses the latest approved assumptions. Adverse weather adds the forecast fuel requirement once. Preventive intervention represents an early allocation review, not a confirmed action.</p></div><div className="scenario-grid"><div><span>BASELINE</span><strong>{formatKg(17000)}</strong><small>cargo capacity · CX257</small></div><div className="scenario-adverse"><span>ADVERSE WEATHER</span><strong>{formatKg(forecasts[0].forecastCargoCapacity)}</strong><small>{formatKg(forecasts[0].forecastCapacityShortfall)} shortfall · {Math.round(forecasts[0].forecastOffloadProbability * 100)}% flight risk</small></div><div className="scenario-prevent"><span>PREVENTIVE INTERVENTION</span><strong>{formatCurrency(12200)}</strong><small>estimated loss avoided · review allocation now</small></div></div></section><footer>All records, forecasts, weather observations, and financial estimates are fictional simulated data. Approved payload calculations and live operational feeds are pending backend integration.</footer></main>{selectedFlight && <FlightDrawer flight={selectedFlight} onClose={() => setSelectedFlight(null)} />}{selectedShipment && <ShipmentDrawer shipment={selectedShipment} onClose={() => setSelectedShipment(null)} />}{selectedRecovery && <RecoveryDrawer option={selectedRecovery} onClose={() => setSelectedRecovery(null)} />}</div>
}

export default App
